def _embedded():
    return json.loads(zlib.decompress(base64.b85decode(''.join(_BUNDLE))))


class Store:
    def __init__(self, root):
        self.root = Path(root)
        self.data, self.digests, self.raws = {}, {}, {}

    def raw(self, path, raw):
        path = str(path)
        ref = {'path': path, 'sha256': hashlib.sha256(raw).hexdigest()}
        self.data[path], self.digests[path], self.raws[path] = json.loads(raw), ref['sha256'], raw
        return ref

    def put(self, path, value):
        return self.raw(path, (json.dumps(value, indent=2, allow_nan=False) + '\n').encode())

    def get(self, ref, successful=True):
        assert type(ref) is dict and set(ref) == {'path', 'sha256'}
        assert self.digests[ref['path']] == ref['sha256']
        value = self.data[ref['path']]
        if successful:
            assert value.get('completed') is True and value.get('failure') is None
        return value


def _metadata(rows, owner, physical):
    result = []
    for row in rows:
        native = row['direction'] in ('to_native', 'from_native')
        result.append({'event': 'native_packet' if native else 'modern_packet',
            'session': owner if native or row['name'] == 'SMSG_STAND_STATE_UPDATE' else physical,
            'name': row['name'], 'direction': row['direction'],
            'bytes': len(bytes.fromhex(row['body'])), 'time': row['time'] - .00001})
    return result


def _quartet(owner, wanted, start):
    shapes = [('CMSG_STAND_STATE_CHANGE', 'from_client', bytes([wanted])),
        ('CMSG_STANDSTATECHANGE', 'to_native', wanted.to_bytes(4, 'little')),
        ('SMSG_STAND_STATE_UPDATE', 'from_native', bytes([wanted])),
        ('SMSG_STAND_STATE_UPDATE', 'to_client', bytes([wanted]) + bytes(4))]
    return [{'session': owner, 'name': name, 'direction': direction,
        'body': raw.hex(), 'time': start + i * .01} for i, (name, direction, raw) in enumerate(shapes)]


def fixture(tmp_path, *, cycles=1, with_afk=True):
    """Return all source values and a mutable, genuinely hashed in-memory store."""
    embedded = _embedded()
    failed = json.loads(embedded['failed_raw'])
    batch = Path(failed['preparation_source']['path']).parents[1]
    store = Store(batch.parents[1])
    failed_ref = store.raw(batch / 'entry01/episode.json', embedded['failed_raw'].encode())
    ready_ref = store.raw(failed['preparation_source']['path'], embedded['ready_raw'].encode())
    facts_ref = store.raw(batch / 'entry_failure_readonly01/facts.json', embedded['initial_raw'].encode())
    ready, initial = store.get(ready_ref), store.get(facts_ref, False)
    assert failed_ref['sha256'] == 'cb64cec0472f9a23d176fbf1e98710aee72b0c195f03ca62b60355f7d994213f'
    assert ready_ref == failed['preparation_source']
    assert facts_ref['sha256'] == '707b10512dbdb0fd1645ef4ad90f5c7ff6e3ca4a1357dee3c9b30b487b2caa62'
    source_bytes = []
    repo = Path('/home/runiir/Games/trinity-442-compatibility')
    for member in embedded['source_bytes']:
        raw = member['raw'].encode()
        source_bytes.append({'path': str(repo / member['path']), 'sha256': hashlib.sha256(raw).hexdigest(),
            'bytes': len(raw), 'raw_hex': raw.hex()})
    original = idle.original_objects(failed['raw_entry_packets'])
    owner, physical = ready['native_session'], '04aa8d2f'
    old_png = {'path': str(batch / 'entry01/bags_swap_entered.png'),
        'sha256': '322ad4584ddaffe7cf6c43ba54bebaa9c39b8fef20bd10b8e01553e1dfe7c76f'}
    store.digests[old_png['path']] = old_png['sha256']
    world_position = [-8914.900390625, -135.60000610351562, 0.0, 0.0]
    public = stock_public(ready['all_offline_snapshot']['2']['saved']['actions'])
    public['keys'] = {'SITORSTAND': ['X']}
    sources = [{k: v[k] for k in ('path', 'sha256')} for v in source_bytes]

    def frame(directory, label):
        result = deepcopy(ready['frame'])
        result.update(file=label + '.png', sha256=hashlib.sha256(('fixture-image:' + label).encode()).hexdigest(),
            movement={'speed': 0, 'dead': False, 'in_combat': False, 'on_taxi': False})
        store.digests[str(directory / result['file'])] = result['sha256']
        return result

    def facts(directory, label, observed, stand=0, afk=False):
        return {'observed_at': observed, 'snapshot': deepcopy(initial['after']),
            'native_state': {**deepcopy(idle.ORIGINAL), 'pose': {'stand': stand, 'sheath': 0}, 'afk': afk},
            'resources': deepcopy(initial['resources']),
            'state': {'player': 'Harnesstwo', 'guid': 'Player-1-00000002', 'level': 1,
                'world_position': deepcopy(world_position), 'cursor_info': {}, 'bags': [], 'panels': [],
                'spell_targeting': False, 'lua_errors': [], 'blocked_actions': []},
            'frame': frame(directory, label), 'public': deepcopy(public)}

    def trial(phase, start, finish):
        return {'schema': 'client442_bag_swap_excluded_idle_housekeeping_v1', 'phase': phase,
            'completed': True, 'failure': None, 'started_at': start, 'finished_at': finish,
            'actor': deepcopy(ready['actor']), 'runtime': deepcopy(ready['runtime']),
            'code_commit': 'e' * 40, 'committed_source_bytes': deepcopy(source_bytes),
            'controller': 'code', 'model': None, 'revision': None, 'fine_tuned': False,
            'qualification_added': False, 'custom_script_permission': 'blocked_by_user',
            'softTargetInteract': deepcopy(failed['softTargetInteract']), 'cases': [], 'cleanup': [],
            'observer_file_sha256': ready['observer_file_sha256'],
            'compatibility_addon_sha256': ready['compatibility_addon_sha256'],
            'preparation_source': ready_ref, 'original_entry_source': failed_ref,
            'native_session': owner, 'excluded_housekeeping': True, 'first_failure_excluded': True,
            'original_failed_image': deepcopy(old_png), 'original_world_position': deepcopy(world_position),
            'original_native_objects': deepcopy(original), 'original_resources_source': facts_ref,
            'original_resources': deepcopy(initial['resources']), 'input_sent': False, 'mutation_sent': False,
            'ordinary_inputs': []}

    all_rows, all_events, values = [], [], []
    since = failed['finished_at']
    prior_ref = None
    for cycle in range(cycles):
        prefix = 'synthetic_idle_' + str(cycle + 1)
        cap_dir, restore_dir, review_dir = [batch / (prefix + suffix) for suffix in ('_capture', '_restore', '_review')]
        sit_time = since + 300
        rows = _quartet(owner, 1, sit_time)
        sit_effect = dict(native_packet({68: 1, 148: 2}, creation=False, time=sit_time + .05), session=owner)
        rows.append(sit_effect)
        events = _metadata(rows, owner, physical)
        events.extend([{'event': 'modern_packet', 'session': owner, 'name': 'CMSG_CHAT_MESSAGE_AFK',
            'direction': 'from_client', 'bytes': 5, 'time': sit_time + .015},
            {'event': 'native_packet', 'session': owner, 'name': 'CMSG_MESSAGECHAT_AFK',
                'direction': 'to_native', 'bytes': 5, 'time': sit_time + .016}])
        events.sort(key=lambda r: r['time'])
        cap_start = sit_time + 5
        before = facts(cap_dir, prefix + '_seated', cap_start + .5, 1, True)
        gap = idle.automatic_idle(rows, events, owner, physical, since, before['observed_at'], original=original)
        cap = trial('bags_swap_idle_housekeeping_captured', cap_start, cap_start + 1)
        cap.update(before=before, frame=before['frame'], automatic_idle=gap)
        if prior_ref is not None:
            cap['prior_housekeeping_source'] = prior_ref
        cap_ref = store.put(cap_dir / 'episode.json', cap)
        review = {'reviewed': True, 'control': 'bags.swap_item.idle_housekeeping',
            'source': cap_ref, 'frame': deepcopy(cap['frame']), 'ordinary_stand_afk_only': True}
        store.digests[str(review_dir / cap['frame']['file'])] = cap['frame']['sha256']
        review_ref = store.put(review_dir / 'review.json', review)
        start = cap['finished_at'] + 1
        inputs = [{'kind': 'stand', 'input': {'kind': 'key', 'value': 'x', 'hold': .4},
            'preflight': facts(restore_dir, prefix + '_stand_preflight', start + .1, 1, True),
            'started_at': start + .2, 'finished_at': start + .8, 'input_replayed': False}]
        stand_rows = _quartet(owner, 0, start + .3)
        stand_effect = dict(native_packet({68: 0, 148: 2 if with_afk else 0}, creation=False,
            time=start + .35), session=owner)
        restored_rows = [*stand_rows, stand_effect]
        restored_events = _metadata(restored_rows, owner, physical)
        if with_afk:
            inputs.append({'kind': 'afk', 'input': {'kind': 'chat', 'value': '/afk'},
                'preflight': facts(restore_dir, prefix + '_afk_preflight', start + 1.1, 0, True),
                'started_at': start + 1.2, 'finished_at': start + 1.8, 'input_replayed': False})
            restored_events.extend([{'event': 'modern_packet', 'session': owner, 'name': 'CMSG_CHAT_MESSAGE_AFK',
                'direction': 'from_client', 'bytes': 5, 'time': start + 1.3},
                {'event': 'native_packet', 'session': owner, 'name': 'CMSG_MESSAGECHAT_AFK',
                    'direction': 'to_native', 'bytes': 5, 'time': start + 1.31}])
            afk_effect = dict(native_packet({148: 0}, creation=False, time=start + 1.35), session=owner)
            restored_rows.append(afk_effect)
            restored_events.extend(_metadata([afk_effect], owner, physical))
        rows += restored_rows
        events += restored_events
        events.sort(key=lambda r: r['time'])
        after = facts(restore_dir, prefix + '_restored', start + 2.4)
        H = trial('bags_swap_idle_housekeeping_restored', start, start + 2.5)
        H.update(capture_source=cap_ref, review_source=review_ref, before=deepcopy(before),
            after=after, frame=after['frame'], automatic_idle=gap, ordinary_inputs=inputs,
            input_sent=True, source_packets=deepcopy(all_rows + rows), source_events=deepcopy(all_events + events),
            cleanup_history=idle.cleanup_history(cap, rows, events, inputs, after['observed_at']))
        if prior_ref is not None:
            H['prior_housekeeping_source'] = prior_ref
        cycle_value = {'original_entry_source': failed_ref,
            'automatic_stand_packets': gap['automatic_stand_packets'], 'automatic_owner_update': gap['automatic_owner_update']}
        cycle_sha = hashlib.sha256(json.dumps(cycle_value, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()).hexdigest()
        marker_refs = []
        for row in inputs:
            marker = {'schema': 'client442_bag_swap_idle_consumed_input_v1', 'kind': row['kind'],
                'created_at': row['started_at'] - .01, 'original_entry_source': failed_ref,
                'cycle_sha256': cycle_sha, 'capture_source': cap_ref, 'operation_output': str(restore_dir / 'episode.json'),
                'input_intent': deepcopy(row['input']), 'input_replay_allowed': False}
            ref = store.put(batch / 'entry01' / ('bag_swap_idle_' + cycle_sha + '_' + row['kind'] + '_attempt.json'), marker)
            H[row['kind'] + '_attempt_source'] = ref
            marker_refs.append(ref)
        H_ref = store.put(restore_dir / 'episode.json', H)
        values.append({'H': H, 'H_ref': H_ref, 'capture': cap, 'capture_ref': cap_ref,
            'review': review, 'review_ref': review_ref, 'marker_refs': marker_refs})
        all_rows += rows
        all_events += events
        since, prior_ref = H['finished_at'], H_ref
    E = {'actor': deepcopy(ready['actor']), 'runtime': deepcopy(ready['runtime']), 'native_session': owner,
        'code_commit': 'f' * 40, 'committed_sources': sources, 'started_at': H['finished_at'] + 1,
        'finished_at': H['finished_at'] + 2, 'idle_housekeeping_source': H_ref,
        'original_entry_source': failed_ref, 'preparation_source': ready_ref,
        'current_snapshot': deepcopy(initial['after']), 'native_original': deepcopy(idle.ORIGINAL),
        'state': deepcopy(after['state']), 'frame': deepcopy(after['frame']),
        'raw_entry_packets': deepcopy(failed['raw_entry_packets'] + all_rows)}
    return {'store': store, 'H': H, 'ready': ready, 'failed': failed, 'E': E, 'ref': H_ref,
        'cycles': values, 'rows': all_rows, 'events': all_events, 'ready_ref': ready_ref,
        'failed_ref': failed_ref, 'facts_ref': facts_ref}


def validate(value):
    return idle.validate_receipt(*(value[k] for k in ('store', 'H', 'ready', 'failed', 'E')))


def _seal(value):
    value['ref'] = value['store'].put(value['ref']['path'], value['H'])
    value['E']['idle_housekeeping_source'] = value['ref']


@pytest.mark.parametrize('cycles,with_afk', [(1, True), (1, False), (2, True)])
def test_source_owned_restoration_is_pure_and_keeps_failed_entry_excluded(tmp_path, monkeypatch, cycles, with_afk):
    value = fixture(tmp_path, cycles=cycles, with_afk=with_afk)
    before = deepcopy(value['store'].data)
    def forbidden(*args, **kwargs):
        raise AssertionError('portable idle validation attempted live filesystem, Git or UI access')
    with monkeypatch.context() as blocked:
        for name in ('read_bytes', 'read_text', 'open', 'stat', 'is_file', 'is_dir', 'is_symlink', 'resolve'):
            blocked.setattr(Path, name, forbidden)
        for name in ('check_output', 'run', 'Popen'):
            blocked.setattr(subprocess, name, forbidden)
        for name in ('open', 'stat', 'lstat'):
            blocked.setattr(os, name, forbidden)
        blocked.setattr(builtins, 'open', forbidden)
        blocked.setitem(sys.modules, 'tools.client_compatibility.interaction_bag_swap_idle_housekeeping', None)
        proof = validate(value)
        rebuilt = idle.validate_history(proof)
    assert rebuilt == proof
    assert len(proof['cycles']) == cycles
    assert value['store'].data == before
    assert value['failed']['completed'] is False
    assert value['failed']['phase'] == 'bags_swap_entry_started'


def test_full_native_replay_accepts_only_the_source_owned_excluded_pose_updates(tmp_path):
    value = fixture(tmp_path)
    proof = validate(value)
    recorded_value = recorded()
    failed = value['failed']
    pose = [failed['native_before_entry'][k] for k in ('position_x', 'position_y', 'position_z', 'orientation')]
    sync = login.login_sync(failed['raw_entry_packets'], recorded_value['events'], value['ready']['native_session'],
        failed['started_at'], failed['finished_at'], pose)
    rows = failed['raw_entry_packets'] + value['rows']
    replay = contract.native_replay(rows, value['ready']['native_session'], failed['started_at'],
        value['E']['finished_at'], login_sync=sync, idle_housekeeping=proof)
    assert replay['owner'] == 2 and replay['health'] == replay['max_health'] == 60


@pytest.mark.parametrize('fault', ['source_bytes', 'source_member', 'marker_replay', 'marker_cycle',
    'marker_owner', 'review_control', 'review_source', 'review_png', 'owned_png', 'native_health',
    'native_field', 'metadata_extra', 'metadata_foreign', 'failed_completed', 'failed_source', 'prior_missing'])
def test_idle_authority_rejects_source_input_effect_and_prior_chain_drift(tmp_path, fault):
    value = fixture(tmp_path, cycles=2 if fault == 'prior_missing' else 1)
    H, store = value['H'], value['store']
    if fault == 'source_bytes': H['committed_source_bytes'][0]['raw_hex'] = '00'
    elif fault == 'source_member': H['committed_source_bytes'].pop()
    elif fault.startswith('marker_'):
        ref = H['stand_attempt_source']; marker = deepcopy(store.get(ref, False))
        if fault == 'marker_replay': marker['input_replay_allowed'] = True
        elif fault == 'marker_cycle': marker['cycle_sha256'] = '0' * 64
        else: marker['original_entry_source'] = value['ready_ref']
        H['stand_attempt_source'] = store.put(ref['path'], marker)
    elif fault.startswith('review_'):
        ref = H['review_source']; review = deepcopy(store.get(ref, False))
        if fault == 'review_control': review['control'] = 'bags.swap_item'
        elif fault == 'review_source': review['source'] = value['failed_ref']
        else: review['frame']['sha256'] = '0' * 64
        H['review_source'] = store.put(ref['path'], review)
    elif fault == 'owned_png':
        store.digests[str(Path(H['capture_source']['path']).parent / H['before']['frame']['file'])] = '0' * 64
    elif fault == 'native_health': H['after']['native_state']['health'] = 59
    elif fault == 'native_field':
        row = dict(native_packet({25: 59}, creation=False, time=H['after']['observed_at'] - .01), session=H['native_session'])
        H['source_packets'].append(row)
        H['source_events'].extend(_metadata([row], H['native_session'], '04aa8d2f'))
    elif fault == 'metadata_extra':
        H['source_events'].append({'event': 'modern_packet', 'session': H['native_session'],
            'name': 'CMSG_SET_ACTION_BUTTON', 'direction': 'from_client', 'bytes': 5, 'time': H['started_at'] + .5})
        H['source_events'].sort(key=lambda row: row['time'])
    elif fault == 'metadata_foreign':
        next(e for e in H['source_events'] if e.get('name') == 'CMSG_STAND_STATE_CHANGE')['session'] = 'foreign'
    elif fault == 'failed_completed': value['failed']['completed'] = True
    elif fault == 'failed_source': H['original_entry_source'] = value['ready_ref']
    elif fault == 'prior_missing': del H['prior_housekeeping_source']
    _seal(value)
    with pytest.raises((RuntimeError, AssertionError)):
        validate(value)
